class Doc:
 def __init__(self,name,wide=False):
  self.w,self.h=(960,540) if wide else (595,842); self.c=canvas.Canvas(str(OUT/name),pagesize=(self.w,self.h));self.n=0;self.name=name; self.c.setTitle(name[:-4].replace('_',' ')); self.c.setAuthor('Team 1 - T3.2605.E1.FPT')
 def page(self,title,label='MAISON RUE'):
  if self.n:self.c.showPage()
  self.n+=1;c=self.c;c.setFillColor(HexColor('#faf8f3'));c.rect(0,0,self.w,self.h,stroke=0,fill=1)
  c.setFillColor(HexColor('#8c714e'));c.setFont('Helvetica',9);c.drawString(42,self.h-35,label.upper());c.setFillColor(HexColor('#29211b'));c.setFont('Times-Roman',27);c.drawString(42,self.h-75,title)
  c.setFont('Helvetica',8);c.setFillColor(HexColor('#8c714e'));c.drawString(42,23,'MAISON RUE  |  TEAM 1 - T3.2605.E1.FPT');c.drawRightString(self.w-42,23,str(self.n));self.y=self.h-103
 def p(self,text,sty=body):
  p=Paragraph(text,sty);_,h=p.wrap(self.w-84,700)
  if self.y-h<45:raise ValueError((self.name,self.n,text[:50],self.y,h))
  p.drawOn(self.c,42,self.y-h);self.y-=h+10
 def section(self,title,text):self.p('<b>'+title+'</b><br/>'+text)
 def pic(self,name,height=330):
  path=IM/(name+'.png'); im=Image.open(path); w=min(self.w-84,height*im.width/im.height);h=w*im.height/im.width
  if self.y-h<45:raise ValueError(('image',self.name,self.n,self.y,h))
  self.c.drawImage(str(path),42,self.y-h,width=w,height=h);self.y-=h+12
 def table(self,rows,widths=None):
  data=[[Paragraph(str(x),small) for x in row] for row in rows]
  t=Table(data,colWidths=widths or [(self.w-84)/len(rows[0])]*len(rows[0]));t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#e6e0d7')),('GRID',(0,0),(-1,-1),.5,HexColor('#d9d9d9')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));_,h=t.wrap(self.w-84,700)
  if self.y-h<45:raise ValueError(('table',self.n,h,self.y))
  t.drawOn(self.c,42,self.y-h);self.y-=h+16
 def flow(self,labels):
  for i,s in enumerate(labels):
   self.c.setStrokeColor(HexColor('#aa9578'));self.c.setFillColor(HexColor('#efe9df'));self.c.rect(65,self.y-40,self.w-130,40,fill=1,stroke=1)
   p=Paragraph(s,small);_,h=p.wrap(self.w-150,36);p.drawOn(self.c,75,self.y-20-h/2);self.y-=40
   if i<len(labels)-1:self.c.line(self.w/2,self.y,self.w/2,self.y-16); self.y-=20
  self.y-=15
 def done(self):self.c.save();print(self.name,self.n)

