d.page('Role and access matrix');d.table([['Capability','Visitor','Customer','Staff','Admin'],['Browse and guest wishlist','Yes','Yes','Public','Public'],['Customer account and returns','No','Own records','No','No'],['Orders and stock operations','No','Own orders','Yes','Yes'],['Return receipt and inspection','No','View own','Yes','Yes'],['Return resolution API','No','No','Yes','Yes'],['Employee and campaign management','No','No','No','Yes'],['Reports and review moderation','No','No','No','Yes']],[215,74,74,74,74]);d.section('Server enforcement','UI navigation is supplemented by API authentication, role checks and customer ownership checks. A separate order payment refund endpoint is admin only.');d.section('Nonfunctional requirements','Maintain readable responsive screens, predictable validation, stock consistency, session protection and useful error feedback. These are verification targets; a feature inventory alone does not establish a complete security or performance certification.')
d.page('Requirement analysis');d.section('Inputs','Credentials, search criteria, variant and quantity selection, delivery data, promo codes, order actions, return reasons, inspection notes, reviews, stock changes and campaign parameters.');d.section('Outputs','Filtered products, calculated prices, order confirmations and histories, return decisions, stock movements, reviews, employee records and business reports.');d.section('Core processes','Authentication; product discovery; cart and checkout; promotion evaluation; order fulfilment; address and account management; return triage and physical inspection; refund and exchange completion; reporting.');d.section('Software','React, React Router, Vite, Node.js, Express and Microsoft SQL Server. Optional external services support addresses, assistant responses and email.');d.section('Scope boundaries','No trained purchase history recommender is demonstrated by the current implementation. Google and chat integrations require service configuration. A database refund record is distinct from a bank payout.')
