d.page('Checkout data flow');d.flow(['Customer selects product variant and quantity','Cart collects selected items and delivery data','API validates cart and evaluates promotion rules','Order and item snapshots preserve purchase information','Payment state and order fulfilment progress are recorded','Customer views order history']);d.section('Failure handling','Reject invalid inputs and unavailable stock. Present the server error to the customer without claiming an order or payment succeeded.')
d.page('Return decision flow');d.flow(['Verify customer ownership and prevent duplicate request','Check delivery and 14 day deadline; validate quantity','Apply promotional exclusion unless a store fault is reported','Check requested amount >= VND 10 million or quantity >= 3','Check reason and condition confirmation','Return authorisation, automatic decline or manual review']);d.p('Initial authorisation is permission to proceed with a return, not final confirmation of a refund.',small)
d.page('Return completion and inventory');d.flow(['Authorised request → in transit → received','Physical inspection with mandatory pass or fail notes','Failed inspection → customer decision; no completion','Passed inspection → refund or exchange completion','Restore returned quantity to original variant','For exchange also deduct replacement quantity and record movements']);d.section('Review eligibility','Refund completion blocks review. Pending and failed requests also block review. A successfully completed exchange can remain eligible.');d.section('Transaction boundary','Completion and stock movements must succeed together. An invalid original variant or insufficient replacement stock must not leave a partial update.')
