# Render all files for visual review and verify page content stays within bounds.
qa=ROOT/'tmp/four-docs-qa';qa.mkdir(exist_ok=True)
for file in sorted(OUT.glob('*.pdf')):
 pdf=pdfium.PdfDocument(str(file)); thumbs=[]
 for i in range(len(pdf)):
  im=pdf[i].render(scale=1).to_pil(); im.save(qa/f'{file.stem}-{i+1:02d}.png');im.thumbnail((238,337));thumbs.append(im)
 for batch in range(0,len(thumbs),12):
  subset=thumbs[batch:batch+12];sheet=Image.new('RGB',(952,337*((len(subset)+3)//4)),'white')
  for j,im in enumerate(subset):sheet.paste(im,((j%4)*238,(j//4)*337))
  sheet.save(qa/f'{file.stem}-sheet-{batch//12}.png')
